"use client";

import { ChevronDown, ChevronRight } from "lucide-react";
import { Fragment, useMemo, useState } from "react";
import type { ReactNode } from "react";
import { cn } from "@/lib/cn";
import { EmptyState } from "@/components/ui/empty-state";
import { Pagination } from "@/components/ui/pagination";
import { Table } from "@/components/ui/table";
import { DataTableLoading } from "@/components/ui/data-table-loading";
import {
  DataTableHeaderRow,
  DataTableRowActionsCell,
  renderCellContent,
} from "@/components/ui/data-table-parts";
import type { DataTableVirtualizedOptions } from "@/components/ui/data-table-virtualized";
import { DataTableVirtualizedBody } from "@/components/ui/data-table-virtualized";
import { useDataTableSort } from "@/components/ui/use-data-table-sort";

/**
 * DataTable — generic, sortable, expandable composite over `<Table>`.
 *
 * Adds operator-grade entity-list patterns on top of the plain Table
 * primitive: sortable headers, sticky header, expandable rows
 * (multi-row by default), row action menus (Dropdown), client-side
 * pagination, loading skeleton rows, empty state. Both sort and
 * pagination support controlled OR uncontrolled mode (consumer
 * passes onSortChange / onPageChange to take over state).
 *
 * `virtualized` mode (M6) renders 10K+ rows over @tanstack/react-virtual.
 * It is mutually exclusive with `pagination` and `expandable` at the type
 * level — a virtualized list is one continuous scroll of fixed-height rows.
 *
 * @example
 *   <DataTable
 *     columns={[
 *       { key: "name", label: "Name", sortable: true },
 *       { key: "status", label: "Status" },
 *     ]}
 *     data={domains}
 *     rowKey={(d) => d.id}
 *     expandable={(d) => d.status === "pending" ? <DnsRecords domain={d} /> : null}
 *     rowActions={(d) => (
 *       <>
 *         <DropdownMenu.Item onSelect={() => editDomain(d)}>Edit</DropdownMenu.Item>
 *         <DropdownMenu.Item onSelect={() => deleteDomain(d)}>Delete</DropdownMenu.Item>
 *       </>
 *     )}
 *   />
 */
export interface DataTableColumn<T> {
  key: string;
  label: ReactNode;
  align?: "left" | "center" | "right";
  sortable?: boolean;
  width?: string;
  render?: (row: T) => ReactNode;
  className?: string;
}

export interface DataTableSort {
  key: string;
  direction: "asc" | "desc";
}

export interface DataTableBaseProps<T> {
  data: T[];
  columns: DataTableColumn<T>[];
  rowKey: (row: T) => string;
  stickyHeader?: boolean;
  rowActions?: (row: T) => ReactNode;
  defaultSort?: DataTableSort;
  sort?: DataTableSort | null;
  onSortChange?: (sort: DataTableSort | null) => void;
  loading?: boolean;
  emptyState?: ReactNode;
  className?: string;
}

/**
 * Discriminated union: the default mode keeps pagination/expandable; the
 * virtualized mode excludes them at the type level (fixed-height single
 * scroll — see DataTableVirtualizedOptions for the documented limitations).
 */
export type DataTableProps<T> = DataTableBaseProps<T> &
  (
    | {
        virtualized?: never;
        expandable?: (row: T) => ReactNode | null;
        expandMode?: "single" | "multiple";
        pagination?: {
          pageSize: number;
          controlledPage?: number;
          onPageChange?: (page: number) => void;
        } | null;
      }
    | {
        virtualized: DataTableVirtualizedOptions;
        expandable?: never;
        expandMode?: never;
        pagination?: never;
        stickyHeader?: never;
      }
  );

function DataTable<T>(props: DataTableProps<T>): ReactNode {
  if (props.virtualized) {
    return <DataTableVirtualizedBody {...props} virtualized={props.virtualized} />;
  }
  return <DataTableDefaultBody {...props} />;
}

function DataTableDefaultBody<T>(props: DataTableProps<T>): ReactNode {
  const {
    data,
    columns,
    rowKey,
    stickyHeader = true,
    expandable,
    expandMode = "multiple",
    rowActions,
    pagination,
    defaultSort,
    sort: controlledSort,
    onSortChange,
    loading = false,
    emptyState,
    className,
  } = props;

  const isControlledPage = pagination?.controlledPage !== undefined;
  const [uncontrolledPage, setUncontrolledPage] = useState(0);
  const currentPage = isControlledPage ? (pagination?.controlledPage ?? 0) : uncontrolledPage;

  // EC-9: clamp pageSize to >= 1 to avoid divide-by-zero / infinite render
  const effectivePageSize = Math.max(1, pagination?.pageSize ?? 10);

  const [expanded, setExpanded] = useState<Set<string>>(new Set());

  const { sort, handleSort, sortedData } = useDataTableSort({
    data,
    columns,
    defaultSort,
    sort: controlledSort,
    onSortChange,
    // EC-8: sort change resets pagination to page 0
    onUncontrolledSortChange: () => {
      if (!isControlledPage) setUncontrolledPage(0);
    },
  });

  function handlePageChange(page: number) {
    // Pagination uses 1-indexed; internal state 0-indexed
    const zeroIdx = page - 1;
    if (isControlledPage) {
      pagination?.onPageChange?.(zeroIdx);
    } else {
      setUncontrolledPage(zeroIdx);
    }
  }

  function toggleExpand(key: string) {
    if (expandMode === "single") {
      setExpanded((prev) => (prev.has(key) ? new Set() : new Set([key])));
    } else {
      setExpanded((prev) => {
        const next = new Set(prev);
        if (next.has(key)) {
          next.delete(key);
        } else {
          next.add(key);
        }
        return next;
      });
    }
  }

  // Apply client-side pagination in uncontrolled mode
  const visibleData = useMemo(() => {
    if (!pagination) return sortedData;
    if (isControlledPage) return sortedData; // consumer pre-sliced
    const start = currentPage * effectivePageSize;
    return sortedData.slice(start, start + effectivePageSize);
  }, [sortedData, pagination, isControlledPage, currentPage, effectivePageSize]);

  // EC-1 fix: compute colSpan accounting for chevron + actions columns
  const extraCols = (expandable ? 1 : 0) + (rowActions ? 1 : 0);
  const expandedColSpan = columns.length + extraCols;

  // Loading state (EC-7: loading > empty)
  if (loading) {
    return (
      <DataTableLoading
        columns={columns}
        hasExpandColumn={expandable !== undefined}
        hasActionsColumn={rowActions !== undefined}
        stickyHeader={stickyHeader}
        className={className}
      />
    );
  }

  // Empty state (after loading check)
  if (sortedData.length === 0) {
    return (
      <div className={cn("w-full", className)}>
        {emptyState ?? <EmptyState title="No data" description="There's nothing here yet." />}
      </div>
    );
  }

  const totalPages = pagination ? Math.ceil(sortedData.length / effectivePageSize) : 1;

  return (
    <div className={cn("w-full", className)}>
      <Table>
        <Table.Header className={stickyHeader ? "sticky top-0 z-10 bg-card" : undefined}>
          <DataTableHeaderRow
            columns={columns}
            sort={sort}
            onSortClick={handleSort}
            hasExpandColumn={expandable !== undefined}
            hasActionsColumn={rowActions !== undefined}
          />
        </Table.Header>
        <Table.Body>
          {visibleData.map((row) => {
            const key = rowKey(row);
            const expandedContent = expandable ? expandable(row) : null;
            const isExpandable = expandedContent !== null && expandedContent !== undefined;
            const isExpanded = expanded.has(key);
            return (
              <Fragment key={key}>
                <Table.Row>
                  {expandable ? (
                    <Table.Cell>
                      {isExpandable ? (
                        <button
                          type="button"
                          onClick={() => toggleExpand(key)}
                          aria-expanded={isExpanded}
                          aria-controls={`expanded-${key}`}
                          aria-label={isExpanded ? "Collapse row" : "Expand row"}
                          className="inline-flex items-center justify-center rounded-md p-0.5 hover:bg-muted"
                        >
                          {isExpanded ? (
                            <ChevronDown aria-hidden="true" className="size-4" />
                          ) : (
                            <ChevronRight aria-hidden="true" className="size-4" />
                          )}
                        </button>
                      ) : null}
                    </Table.Cell>
                  ) : null}
                  {columns.map((col) => (
                    <Table.Cell key={col.key} align={col.align} className={col.className}>
                      {renderCellContent(row, col)}
                    </Table.Cell>
                  ))}
                  {rowActions ? (
                    <DataTableRowActionsCell>{rowActions(row)}</DataTableRowActionsCell>
                  ) : null}
                </Table.Row>
                {isExpanded && isExpandable ? (
                  <tr id={`expanded-${key}`}>
                    <td colSpan={expandedColSpan} className="bg-muted/30 p-4">
                      {expandedContent}
                    </td>
                  </tr>
                ) : null}
              </Fragment>
            );
          })}
        </Table.Body>
      </Table>
      {pagination && totalPages > 1 ? (
        <div className="mt-4 flex items-center justify-end">
          <Pagination
            currentPage={currentPage + 1}
            totalPages={totalPages}
            onPageChange={handlePageChange}
          />
        </div>
      ) : null}
    </div>
  );
}

export { DataTable };

import { useVirtualizer } from "@tanstack/react-virtual";
import type { VirtualizerOptions } from "@tanstack/react-virtual";
import { useRef } from "react";
import type { ReactNode } from "react";
import { cn } from "@/lib/cn";
import { isDev } from "@/lib/env";
import { EmptyState } from "@/components/ui/empty-state";
import { Table } from "@/components/ui/table";
import { DataTableLoading } from "@/components/ui/data-table-loading";
import {
  DataTableHeaderRow,
  DataTableRowActionsCell,
  renderCellContent,
} from "@/components/ui/data-table-parts";
import type { DataTableBaseProps } from "@/components/ui/data-table";
import { useDataTableSort } from "@/components/ui/use-data-table-sort";

/**
 * Virtualized body of DataTable — renders 10K+ rows over @tanstack/react-virtual
 * (blueprint M6, ADR D1/D2 + review fix F-dom-1). Semantic `<table>` preserved
 * with the SPACER-ROW technique: two fixed-height spacer `<tr>`s grow the
 * table's real layout box to the full dataset height, so the sticky `<thead>`
 * keeps its containing block for the whole scroll and the last row stays
 * reachable — per-row transforms (the official example's pattern) do NOT grow
 * the layout box and un-stick the header after ~one window.
 *
 * Limitations (documented contract — mutually exclusive at the type level):
 * no pagination, no expandable rows (fixed row heights are required by
 * estimateSize). Cell content must fit `rowHeight` (cells are clipped with
 * reduced padding; keep rowHeight >= ~32px). A row-action dropdown unmounts
 * when its row leaves the overscan window.
 */
export interface DataTableVirtualizedOptions {
  /** Scroll container height (px or CSS length). */
  height: number | string;
  /** Fixed row height in px — required by the virtualizer's estimateSize. */
  rowHeight: number;
  /** Rows rendered beyond the viewport on each side. @default 5 */
  overscan?: number;
  /** @internal test-only — inject virtualizer options (e.g. observeElementRect). */
  virtualizerOptions?: Partial<VirtualizerOptions<HTMLElement, Element>>;
}

export type DataTableVirtualizedBodyProps<T> = Omit<DataTableBaseProps<T>, "stickyHeader"> & {
  virtualized: DataTableVirtualizedOptions;
};

const EXCLUSIVE_PROPS = ["pagination", "expandable"] as const;

function SpacerRow(props: { slot: "top" | "bottom"; height: number; colSpan: number }) {
  if (props.height <= 0) return null;
  return (
    // biome-ignore lint/a11y/noInteractiveElementToNoninteractiveRole: spacer row is pure layout filler (no content, no interaction) inside a semantic table; presentation keeps SRs on the aria-rowcount contract
    <tr
      data-slot={`data-table-virtual-spacer-${props.slot}`}
      role="presentation"
      style={{ height: `${props.height}px` }}
    >
      <td colSpan={props.colSpan} style={{ padding: 0 }} />
    </tr>
  );
}

export function DataTableVirtualizedBody<T>(props: DataTableVirtualizedBodyProps<T>): ReactNode {
  const {
    data,
    columns,
    rowKey,
    virtualized,
    rowActions,
    defaultSort,
    sort: controlledSort,
    onSortChange,
    loading = false,
    emptyState,
    className,
  } = props;

  if (isDev()) {
    for (const key of EXCLUSIVE_PROPS) {
      if ((props as unknown as Record<string, unknown>)[key]) {
        // biome-ignore lint/suspicious/noConsole: dev-only diagnostic for mutually-exclusive modes.
        console.warn(
          `DataTable: \`${key}\` is ignored in virtualized mode — the modes are mutually exclusive.`,
        );
      }
    }
    if (virtualized.rowHeight < 1) {
      // biome-ignore lint/suspicious/noConsole: dev-only diagnostic for invalid rowHeight (EC-2).
      console.warn("DataTable: virtualized.rowHeight must be >= 1px — falling back to 1.");
    }
  }
  // EC-2: guard against divide-by-zero window math from untyped consumers
  const rowHeight = Math.max(1, virtualized.rowHeight);

  const parentRef = useRef<HTMLElement>(null);
  const { sort, handleSort, sortedData } = useDataTableSort({
    data,
    columns,
    defaultSort,
    sort: controlledSort,
    onSortChange,
  });

  const virtualizer = useVirtualizer({
    // Injection first (review F-dom-6): the @internal test hook can add
    // observeElementRect but can never override the core window contract.
    ...virtualized.virtualizerOptions,
    count: sortedData.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => rowHeight,
    overscan: virtualized.overscan ?? 5,
  });

  if (loading) {
    return (
      <DataTableLoading
        columns={columns}
        hasExpandColumn={false}
        hasActionsColumn={rowActions !== undefined}
        stickyHeader
        className={className}
      />
    );
  }

  if (sortedData.length === 0) {
    return (
      <div className={cn("w-full", className)}>
        {emptyState ?? <EmptyState title="No data" description="There's nothing here yet." />}
      </div>
    );
  }

  const items = virtualizer.getVirtualItems();
  const totalSize = virtualizer.getTotalSize();
  const firstItem = items[0];
  const lastItem = items[items.length - 1];
  const paddingTop = firstItem ? firstItem.start : 0;
  const paddingBottom = lastItem ? totalSize - lastItem.end : totalSize;
  const colSpan = columns.length + (rowActions ? 1 : 0);

  return (
    <div data-slot="data-table-virtual-body" className={cn("w-full", className)}>
      <section
        ref={parentRef}
        // WCAG 2.1.1 (review F-dom-5): a scrollable region must be reachable
        // and operable by keyboard; <section> + aria-label = implicit region role.
        aria-label="Table scroll area"
        // biome-ignore lint/a11y/noNoninteractiveTabindex: WCAG 2.1.1 / axe scrollable-region-focusable — a keyboard user must be able to focus and scroll the region
        tabIndex={0}
        className="overflow-auto focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        style={{ height: virtualized.height }}
        data-slot="data-table-virtual-scroll"
      >
        <Table aria-rowcount={sortedData.length + 1}>
          <Table.Header className="sticky top-0 z-10 bg-card">
            <DataTableHeaderRow
              columns={columns}
              sort={sort}
              onSortClick={handleSort}
              hasActionsColumn={rowActions !== undefined}
            />
          </Table.Header>
          <Table.Body>
            <SpacerRow slot="top" height={paddingTop} colSpan={colSpan} />
            {items.map((vRow) => {
              const row = sortedData[vRow.index] as T;
              return (
                <Table.Row
                  key={rowKey(row)}
                  aria-rowindex={vRow.index + 2}
                  style={{ height: `${rowHeight}px` }}
                >
                  {columns.map((col) => (
                    <Table.Cell
                      key={col.key}
                      align={col.align}
                      className={cn("overflow-hidden py-1.5", col.className)}
                    >
                      {renderCellContent(row, col)}
                    </Table.Cell>
                  ))}
                  {rowActions ? (
                    <DataTableRowActionsCell>{rowActions(row)}</DataTableRowActionsCell>
                  ) : null}
                </Table.Row>
              );
            })}
            <SpacerRow slot="bottom" height={paddingBottom} colSpan={colSpan} />
          </Table.Body>
        </Table>
      </section>
    </div>
  );
}

import { MoreHorizontal } from "lucide-react";
import type { ReactNode } from "react";
import { cn } from "@/lib/cn";
import { DropdownMenu } from "@/components/ui/dropdown-menu";
import { Table } from "@/components/ui/table";
import type { DataTableColumn, DataTableSort } from "@/components/ui/data-table";

/** Header row shared by the default and virtualized DataTable bodies. */
export function DataTableHeaderRow<T>(props: {
  columns: DataTableColumn<T>[];
  sort: DataTableSort | null;
  onSortClick: (columnKey: string) => void;
  hasExpandColumn?: boolean;
  hasActionsColumn?: boolean;
}): ReactNode {
  const { columns, sort, onSortClick, hasExpandColumn = false, hasActionsColumn = false } = props;
  return (
    <Table.Row>
      {hasExpandColumn ? (
        <Table.HeaderCell>
          <span className="sr-only">Expand</span>
        </Table.HeaderCell>
      ) : null}
      {columns.map((col) => {
        const isSortable = col.sortable === true;
        const isActive = sort?.key === col.key;
        return (
          <Table.HeaderCell
            key={col.key}
            align={col.align}
            onSort={isSortable ? () => onSortClick(col.key) : undefined}
            sortDirection={isSortable ? (isActive ? sort?.direction : "none") : undefined}
            style={col.width ? { width: col.width } : undefined}
          >
            {col.label}
          </Table.HeaderCell>
        );
      })}
      {hasActionsColumn ? (
        <Table.HeaderCell>
          <span className="sr-only">Actions</span>
        </Table.HeaderCell>
      ) : null}
    </Table.Row>
  );
}

/** Row-actions dropdown cell shared by both DataTable bodies. */
export function DataTableRowActionsCell(props: { children: ReactNode }): ReactNode {
  return (
    <Table.Cell align="right">
      <DropdownMenu>
        <DropdownMenu.Trigger
          aria-label="Row actions"
          className={cn(
            "inline-flex size-7 items-center justify-center rounded-md",
            "text-muted-foreground hover:bg-muted hover:text-foreground",
            "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
          )}
        >
          <MoreHorizontal aria-hidden="true" className="size-4" />
        </DropdownMenu.Trigger>
        <DropdownMenu.Content align="end">{props.children}</DropdownMenu.Content>
      </DropdownMenu>
    </Table.Cell>
  );
}

/** Renders a body cell's content per column definition (shared by both bodies). */
export function renderCellContent<T>(row: T, col: DataTableColumn<T>): ReactNode {
  return col.render ? col.render(row) : String((row as Record<string, unknown>)[col.key] ?? "");
}

import type { ReactNode } from "react";
import { cn } from "@/lib/cn";
import { Skeleton } from "@/components/ui/skeleton";
import { Table } from "@/components/ui/table";
import { DataTableHeaderRow } from "@/components/ui/data-table-parts";
import type { DataTableColumn } from "@/components/ui/data-table";

/** Skeleton state shared by both DataTable modes (extracted — 300-line hook floor). */
export function DataTableLoading<T>(props: {
  columns: DataTableColumn<T>[];
  hasExpandColumn: boolean;
  hasActionsColumn: boolean;
  stickyHeader: boolean;
  className?: string;
}): ReactNode {
  const { columns, hasExpandColumn, hasActionsColumn, stickyHeader, className } = props;
  const totalCols = columns.length + (hasExpandColumn ? 1 : 0) + (hasActionsColumn ? 1 : 0);
  return (
    <div data-slot="data-table" className={cn("w-full", className)}>
      <Table>
        <Table.Header className={stickyHeader ? "sticky top-0 bg-card" : undefined}>
          {/* header reutilizado sem affordance de sort (skeleton é inerte) — F-arch-1 */}
          <DataTableHeaderRow
            columns={columns.map((col) => ({ ...col, sortable: false }))}
            sort={null}
            onSortClick={() => {}}
            hasExpandColumn={hasExpandColumn}
            hasActionsColumn={hasActionsColumn}
          />
        </Table.Header>
        <Table.Body>
          {Array.from({ length: 5 }, (_, i) => (
            // biome-ignore lint/suspicious/noArrayIndexKey: skeleton rows are positional placeholders
            <Table.Row key={`skeleton-${i}`}>
              {Array.from({ length: totalCols }, (_, j) => (
                // biome-ignore lint/suspicious/noArrayIndexKey: skeleton cells are positional placeholders
                <Table.Cell key={`s-${i}-${j}`}>
                  <Skeleton className="h-4 w-full" />
                </Table.Cell>
              ))}
            </Table.Row>
          ))}
        </Table.Body>
      </Table>
    </div>
  );
}

import { useMemo, useState } from "react";
import { compareValues } from "@/components/ui/compare-values";
import type { DataTableColumn, DataTableSort } from "@/components/ui/data-table";

/**
 * Shared controlled/uncontrolled sort state for both DataTable modes.
 * Cycle: none → asc → desc → none. Client-side sorting applies only in
 * uncontrolled mode (controlled consumers pre-sort their data).
 */
export function useDataTableSort<T>(opts: {
  data: T[];
  columns: DataTableColumn<T>[];
  defaultSort?: DataTableSort;
  sort?: DataTableSort | null;
  onSortChange?: (sort: DataTableSort | null) => void;
  /** Fired on uncontrolled sort change (EC-8: page reset in paginated mode). */
  onUncontrolledSortChange?: () => void;
}) {
  const { data, columns, defaultSort, sort: controlledSort, onSortChange } = opts;
  const isControlledSort = onSortChange !== undefined;
  const [uncontrolledSort, setUncontrolledSort] = useState<DataTableSort | null>(
    defaultSort ?? null,
  );
  const sort = isControlledSort ? (controlledSort ?? null) : uncontrolledSort;

  function handleSort(columnKey: string) {
    let nextSort: DataTableSort | null;
    if (sort?.key !== columnKey) {
      nextSort = { key: columnKey, direction: "asc" };
    } else if (sort.direction === "asc") {
      nextSort = { key: columnKey, direction: "desc" };
    } else {
      nextSort = null;
    }
    if (isControlledSort) {
      onSortChange?.(nextSort);
    } else {
      setUncontrolledSort(nextSort);
      opts.onUncontrolledSortChange?.();
    }
  }

  const sortedData = useMemo(() => {
    if (isControlledSort || sort === null) return data;
    const col = columns.find((c) => c.key === sort.key);
    if (!col) return data;
    const sorted = [...data].sort((a, b) => {
      const aVal = col.render
        ? null
        : (a as Record<string, unknown>)[sort.key as keyof T as string];
      const bVal = col.render
        ? null
        : (b as Record<string, unknown>)[sort.key as keyof T as string];
      const cmp = compareValues(aVal, bVal);
      return sort.direction === "asc" ? cmp : -cmp;
    });
    return sorted;
  }, [data, sort, isControlledSort, columns]);

  return { sort, handleSort, sortedData };
}

/** Shared sort comparator for DataTable modes (default + virtualized). */
export function compareValues(a: unknown, b: unknown): number {
  if (a === b) return 0;
  if (a === null || a === undefined) return -1;
  if (b === null || b === undefined) return 1;
  if (typeof a === "number" && typeof b === "number") return a - b;
  return String(a).localeCompare(String(b));
}
